def clasificar_pedido(monto: int) -> str:
    """Clasifica un pedido por monto: pequeño, mediano o grande."""
    if monto <= 0:
        raise ValueError(f"Monto inválido: {monto}")
    if monto >= 50_000:
        return "grande"
    if monto >= 10_000:
        return "mediano"
    return "pequeño"


# Los bordes primero: 9 999, 10 000, 49 999 y 50 000
assert [clasificar_pedido(m) for m in (9_999, 10_000, 49_999, 50_000)] == ["pequeño", "mediano", "mediano", "grande"]
for monto in (18_500, -300):
    try:
        print(monto, "->", clasificar_pedido(monto))
    except ValueError as e:
        print("Error:", e)

class Pedido:
    ESTADOS = ("pendiente", "pagado", "enviado", "entregado", "cancelado")

    def __init__(self, numero: int, estado: str = "pendiente"):
        self.numero = numero
        self.estado = estado          # pasa por el setter: también se valida al crear

    @property
    def estado(self) -> str:
        return self._estado

    @estado.setter
    def estado(self, nuevo: str) -> None:
        if nuevo not in self.ESTADOS:
            raise ValueError(f"Estado inválido: {nuevo!r}")
        self._estado = nuevo

    def __str__(self) -> str:
        return f"Pedido #{self.numero} ({self.estado})"


p = Pedido(421)
p.estado = "pagado"
print(p)
try:
    p.estado = "perdido"
except ValueError as e:
    print("Rechazado:", e)
print(p.estado)

class Empleado:
    def __init__(self, nombre: str, salario: int):
        self.nombre = nombre
        self.salario = salario

    def pago_mensual(self, ventas: int = 0) -> int:
        return self.salario

    def __str__(self) -> str:
        return f"{type(self).__name__} {self.nombre}"


class Vendedor(Empleado):
    def __init__(self, nombre: str, salario: int, comision: float):
        super().__init__(nombre, salario)
        self.comision = comision

    def pago_mensual(self, ventas: int = 0) -> int:
        return super().pago_mensual() + round(ventas * self.comision)


planilla = [Empleado("Hugo Sibaja", 610_000), Vendedor("Marco Leiva", 760_000, 0.03)]
for e in planilla:
    print(f"{e}: ₡{e.pago_mensual(ventas=900_000):,}")
print(isinstance(planilla[1], Empleado), isinstance(planilla[0], Vendedor))

from dataclasses import dataclass


@dataclass
class LineaPedido:
    producto: str
    cantidad: int
    precio_unitario: int
    descuento: float = 0.0

    def __post_init__(self):
        if self.cantidad <= 0:
            raise ValueError("La cantidad debe ser positiva")
        if not 0 <= self.descuento < 1:
            raise ValueError("El descuento es una fracción entre 0 y 1")

    @property
    def total(self) -> float:
        # La misma fórmula que usas en SQL: cantidad * precio_unitario * (1 - descuento)
        return self.cantidad * self.precio_unitario * (1 - self.descuento)


lineas = [LineaPedido("Café molido Tarrazú 500 g", 2, 6500, 0.10), LineaPedido("Salsa Lizano 700 ml", 3, 2450)]
print(lineas[1])
print("Total del pedido:", round(sum(l.total for l in lineas)))
print(LineaPedido("Tapa de dulce 1 kg", 1, 1650) == LineaPedido("Tapa de dulce 1 kg", 1, 1650))

