import sqlite3
from dataclasses import dataclass


@dataclass
class Producto:
    nombre: str
    categoria: str
    costo: int
    stock: int

    @property
    def valor(self) -> int:
        return self.costo * self.stock


class InventarioRepositorio:
    def __init__(self, con: sqlite3.Connection):
        self.con = con
        self.con.row_factory = sqlite3.Row

    def activos(self) -> list[Producto]:
        filas = self.con.execute(
            """SELECT p.nombre, c.nombre AS categoria, p.costo, p.stock
               FROM productos p JOIN categorias c ON c.id = p.categoria_id
               WHERE p.activo = 1"""
        ).fetchall()
        return [Producto(f["nombre"], f["categoria"], f["costo"], f["stock"]) for f in filas]

    def valor_por_categoria(self) -> dict[str, int]:
        filas = self.con.execute(
            """SELECT c.nombre, SUM(p.costo * p.stock)
               FROM productos p JOIN categorias c ON c.id = p.categoria_id
               WHERE p.activo = 1
               GROUP BY c.nombre"""
        ).fetchall()
        return {nombre: total for nombre, total in filas}


def valor_en_python(productos: list[Producto]) -> dict[str, int]:
    totales = {}
    for p in productos:
        totales[p.categoria] = totales.get(p.categoria, 0) + p.valor
    return totales


con = sqlite3.connect("tienda.db")
repo = InventarioRepositorio(con)
en_sql = repo.valor_por_categoria()
en_python = valor_en_python(repo.activos())
assert en_sql == en_python, "SQL y Python no coinciden"
for categoria, valor in sorted(en_sql.items(), key=lambda par: par[1], reverse=True):
    print(f"{categoria:<17} ₡{valor:>10,}")
print(f"{'Total':<17} ₡{sum(en_sql.values()):>10,}")
con.close()

